export default {
  props: ["id"],
  data() {
    return {
      product: null
    };
  },
  methods: {
    async getProducts() {
      await fetch(`https://dummyjson.com/products/${this.id}`).then(res => res.json()).then(data => this.product = data);
    }
  },
  async mounted() {
    await this.getProducts();
  }
};
